import{_ as t,a0 as o,w as c,s as r,ao as p,I as e,x as s,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Google Analytics 的一些用法介紹 | LCTT x X-CMD","titleTemplate":false,"description":"Google Analytics 的一些用法介紹 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Google Analytics 的一些用法介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Google Analytics 的一些用法介紹 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191004 All That You Can Do with Google Analytics, and More","title":"Google Analytics 的一些用法介紹","tag":"201910","desc":""},"relativePath":"201910/20191004 All That You Can Do with Google Analytics, and More.md","filePath":"[post].md"}'),d={name:"201910/20191004 All That You Can Do with Google Analytics, and More.md"};function g(h,a,u,k,b,y){const n=o("Link");return c(),r("div",null,[a[21]||(a[21]=p('<h1 id="google-analytics-的一些用法介紹" tabindex="-1">Google Analytics 的一些用法介紹 <a class="header-anchor" href="#google-analytics-的一些用法介紹" aria-label="Permalink to “Google Analytics 的一些用法介紹”">​</a></h1><p><img src="https://i0.wp.com/opensourceforu.com/wp-content/uploads/2019/10/Analytics-illustration.jpg?resize=696%2C396&amp;ssl=1" alt="" title="Analytics illustration"></p><p>Google Analytics （GA）這個最流行的用户活動追蹤工具我們或多或少都聽説過甚至使用過，但它的用途並不僅僅限於對頁面訪問的追蹤。作為一個既實用又流行的工具，它已經受到了廣泛的歡迎，因此我們將要在下文中介紹如何在各種 Angular 和 React 單頁應用中使用 Google Analytics。</p><p>這篇文章源自這樣一個問題：如何對單頁應用中的頁面訪問進行跟蹤？</p><p>通常來説，有很多的方法可以解決這個問題，在這裏我們只討論其中的一種方法。下面我會使用 Angular 來寫出對應的實現，如果你使用的是 React，相關的用法和概念也不會有太大的差別。接下來就開始吧。</p><h3 id="準備好應用程序" tabindex="-1">準備好應用程序 <a class="header-anchor" href="#準備好應用程序" aria-label="Permalink to “準備好應用程序”">​</a></h3><p>首先需要有一個<ruby>追蹤 ID<rt>tracking ID</rt></ruby>。在開始編寫業務代碼之前，要先準備好一個追蹤 ID，通過這個唯一的標識，Google Analytics 才能識別出某個點擊或者某個頁面訪問是來自於哪一個應用。</p><p>按照以下的步驟：</p>',8)),e("ol",null,[e("li",null,[a[1]||(a[1]=s("訪問 ",-1)),l(n,{href:"https://analytics.google.com"},{default:i(()=>[...a[0]||(a[0]=[s("https://analytics.google.com",-1)])]),_:1}),a[2]||(a[2]=s("；",-1))]),a[3]||(a[3]=e("li",null,"提交指定信息以完成註冊，並確保可用於 Web 應用，因為我們要開發的正是一個 Web 應用；",-1)),a[4]||(a[4]=e("li",null,"同意相關的條款，生成一個追蹤 ID；",-1)),a[5]||(a[5]=e("li",null,"保存好追蹤 ID。",-1))]),a[22]||(a[22]=p(`<p>追蹤 ID 拿到了，就可以開始編寫業務代碼了。</p><h3 id="添加-analytics-js-腳本" tabindex="-1">添加 analytics.js 腳本 <a class="header-anchor" href="#添加-analytics-js-腳本" aria-label="Permalink to “添加 analytics.js 腳本”">​</a></h3><p>Google 已經幫我們做好了接入之前需要做的所有事情，接下來就是我們的工作了。不過我們要做的也很簡單，只需要把下面這段腳本添加到應用的 <code>index.html</code> 裏，就可以了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;script&gt;</span></span>
<span class="line"><span>(function(i,s,o,g,r,a,m){i[&#39;GoogleAnalyticsObject&#39;]=r;i[r]=i[r]||function(){</span></span>
<span class="line"><span>(i[r].q=i[r].q||[]).push(arguments)},i[r].l=1*new Date();a=s.createElement(o),</span></span>
<span class="line"><span>m=s.getElementsByTagName(o)[0];a.async=1;a.src=g;m.parentNode.insertBefore(a,m)</span></span>
<span class="line"><span>})(window,document,&#39;script&#39;,&#39;https://www.google-analytics.com/analytics.js&#39;,&#39;ga&#39;);</span></span>
<span class="line"><span>&lt;/script&gt;</span></span></code></pre></div><p>現在我們來看一下 Google Analytics 是如何在應用程序中初始化的。</p><h3 id="創建追蹤器" tabindex="-1">創建追蹤器 <a class="header-anchor" href="#創建追蹤器" aria-label="Permalink to “創建追蹤器”">​</a></h3><p>首先創建一個應用程序的追蹤器。在 <code>app.component.ts</code> 中執行以下兩個步驟：</p><ol><li>聲明一個名為 <code>ga</code>，類型為 <code>any</code> 的全局變量（在 Typescript 中需要制定變量類型）；</li><li>將下面一行代碼加入到 <code>ngInInit()</code> 中。</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ga(&#39;create&#39;, &lt;你的追蹤 ID&gt;, &#39;auto&#39;);</span></span></code></pre></div><p>這樣就已經成功地在應用程序中初始化了一個 Google Analytics 的追蹤器了。由於追蹤器的初始化是在 <code>OnInit()</code> 函數中執行的，因此每當應用程序啓動，追蹤器就會啓動。</p><h3 id="在單頁應用中記錄頁面訪問情況" tabindex="-1">在單頁應用中記錄頁面訪問情況 <a class="header-anchor" href="#在單頁應用中記錄頁面訪問情況" aria-label="Permalink to “在單頁應用中記錄頁面訪問情況”">​</a></h3><p>我們需要實現的是記錄<ruby>訪問路由<rt>route-visits</rt></ruby>。</p><p>如何記錄用户在一個應用中不同部分的訪問，這是一個難點。從功能上來看，單頁應用中的路由對應了傳統多頁面應用中各個頁面之間的跳轉，因此我們需要記錄訪問路由。要做到這一點儘管不算簡單，但仍然是可以實現的。在 <code>app.component.ts</code> 的 <code>ngOnInit()</code> 函數中添加以下的代碼片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import { Router, NavigationEnd } from &#39;@angular/router&#39;;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>constructor(public router: Router) {}</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>this.router.events.subscribe(</span></span>
<span class="line"><span>    event =&gt; {</span></span>
<span class="line"><span>        if (event instanceof NavigationEnd) {</span></span>
<span class="line"><span>            ga(&#39;set&#39;, &#39;page&#39;, event.urlAfterRedirects);</span></span>
<span class="line"><span>            ga(&#39;send&#39;, { hitType: &#39;pageview&#39;, hitCallback: () =&gt; { this.pageViewSent = true; }});</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    } </span></span>
<span class="line"><span>);</span></span></code></pre></div><p>神奇的是，只需要這麼幾行代碼，就實現了 Angular 應用中記錄頁面訪問情況的功能。</p><p>這段代碼實際上做了以下幾件事情：</p><ol><li>從 Angular Router 中導入了 <code>Router</code>、<code>NavigationEnd</code>；</li><li>通過構造函數中將 <code>Router</code> 添加到組件中；</li><li>然後訂閲 <code>router</code> 事件，也就是由 Angular Router 發出的所有事件；</li><li>只要產生了一個 <code>NavigationEnd</code> 事件實例，就將路由和目標作為一個頁面訪問進行記錄。</li></ol><p>這樣，只要使用到了頁面路由，就會向 Google Analytics 發送一條頁面訪問記錄，在 Google Analytics 的在線控制台中可以看到這些記錄。</p><p>類似地，我們可以用相同的方式來記錄除了頁面訪問之外的活動，例如某個界面的查看次數或者時長等等。只要像上面的代碼那樣使用 <code>hitCallBack()</code> 就可以在有需要收集的數據的時候讓應用程序作出反應，這裏我們做的事情僅僅是把一個變量的值設為 <code>true</code>，但實際上 <code>hitCallBack()</code> 中可以執行任何代碼。</p><h3 id="追蹤用户交互活動" tabindex="-1">追蹤用户交互活動 <a class="header-anchor" href="#追蹤用户交互活動" aria-label="Permalink to “追蹤用户交互活動”">​</a></h3><p>除了頁面訪問記錄之外，Google Analytics 還經常被用於追蹤用户的交互活動，例如某個按鈕的點擊情況。“提交按鈕被用户點擊了多少次？”，“產品手冊會被經常查閲嗎？”這些都是 Web 應用程序的產品評審會議上的常見問題。這一節我們將會介紹如何實現這些數據的統計。</p><h4 id="按鈕點擊" tabindex="-1">按鈕點擊 <a class="header-anchor" href="#按鈕點擊" aria-label="Permalink to “按鈕點擊”">​</a></h4><p>設想這樣一種場景，需要統計到應用程序中某個按鈕或鏈接被點擊的次數，這是一個和註冊之類的關鍵動作關係最密切的數據指標。下面我們來舉一個例子：</p><p>假設應用程序中有一個“感興趣”按鈕，用於顯示即將推出的活動，你希望通過統計這個按鈕被點擊的次數來推測有多少用户對此感興趣。那麼我們可以使用以下的代碼來實現這個功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>params = {</span></span>
<span class="line"><span>    eventCategory:</span></span>
<span class="line"><span>    &#39;Button&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventAction:</span></span>
<span class="line"><span>    &#39;Click&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventLabel:</span></span>
<span class="line"><span>    &#39;Show interest&#39;</span></span>
<span class="line"><span>    ,</span></span>
<span class="line"><span>    eventValue:</span></span>
<span class="line"><span>    1</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>showInterest() {</span></span>
<span class="line"><span>    ga(&#39;send&#39;, &#39;event&#39;, this.params);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>現在看下這段代碼實際上做了什麼。正如前面説到，當我們向 Google Analytics 發送數據的時候，Google Analytics 就會記錄下來。因此我們可以向 <code>send()</code> 方法傳遞不同的參數，以區分不同的事件，例如兩個不同按鈕的點擊記錄。</p><p>1、首先我們定義了一個 <code>params</code> 對象，這個對象包含了以下幾個字段：</p><ol><li><code>eventCategory</code> – 交互發生的對象，這裏對應的是按鈕（button）</li><li><code>eventAction</code> – 發生的交互的類型，這裏對應的是點擊（click）</li><li><code>eventLabel</code> – 交互動作的標識，這裏對應的是這個按鈕的內容，也就是“感興趣”</li><li><code>eventValue</code> – 與每個發生的事件實例相關聯的值</li></ol><p>由於這個例子中是要統計點擊了“感興趣”按鈕的用户數，因此我們把 <code>eventValue</code> 的值定為 1。</p><p>2、對象構造完成之後，下一步就是將 <code>params</code> 對象作為請求負載發送到 Google Analytics，而這一步是通過事件綁定將 <code>showInterest()</code> 綁定在按鈕上實現的。這也是使用 Google Analytics 追蹤中最常用的發送事件方法。</p><p>至此，Google Analytics 就可以通過記錄按鈕的點擊次數來統計感興趣的用户數了。</p><h4 id="追蹤社交活動" tabindex="-1">追蹤社交活動 <a class="header-anchor" href="#追蹤社交活動" aria-label="Permalink to “追蹤社交活動”">​</a></h4><p>Google Analytics 還可以通過應用程序追蹤用户在社交媒體上的互動。其中一種場景就是在應用中放置類似 Facebook 的點贊按鈕，下面我們來看看如何使用 Google Analytics 來追蹤這一行為。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>fbLikeParams = {</span></span>
<span class="line"><span>    socialNetwork:</span></span>
<span class="line"><span>        &#39;Facebook&#39;,</span></span>
<span class="line"><span>    socialAction:</span></span>
<span class="line"><span>        &#39;Like&#39;,</span></span>
<span class="line"><span>    socialTarget:</span></span>
<span class="line"><span>        &#39;https://facebook.com/mypage&#39;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>fbLike() {</span></span>
<span class="line"><span>    ga(&#39;send&#39;, &#39;social&#39;, this.fbLikeParams);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果你覺得這段代碼似曾相識，那是因為它確實跟上面統計“感興趣”按鈕點擊次數的代碼非常相似。下面我們繼續看其中每一步的內容：</p><p>1、構造發送的數據負載，其中包括以下字段：</p><ol><li><code>socialNetwork</code> – 交互發生的社交媒體，例如 Facebook、Twitter 等等</li><li><code>socialAction</code> – 發生的交互類型，例如點贊、發表推文、分享等等</li><li><code>socialTarget</code> – 交互的目標 URL，一般是社交媒體賬號的主頁</li></ol><p>2、下一步是增加一個函數來發送整個交互記錄。和統計按鈕點擊數量時相比，這裏使用 <code>send()</code> 的方式有所不同。另外，我們還需要把這個函數綁定到已有的點贊按鈕上。</p><p>在追蹤用户交互方面，Google Analytics 還可以做更多的事情，其中最重要的一種是針對異常的追蹤，這讓我們可以通過 Google Analytics 來追蹤應用程序中出現的錯誤和異常。在本文中我們就不贅述這一點了，但我們鼓勵讀者自行探索。</p><h3 id="用户識別" tabindex="-1">用户識別 <a class="header-anchor" href="#用户識別" aria-label="Permalink to “用户識別”">​</a></h3><h4 id="隱私是一項權利-而不是奢侈品" tabindex="-1">隱私是一項權利，而不是奢侈品 <a class="header-anchor" href="#隱私是一項權利-而不是奢侈品" aria-label="Permalink to “隱私是一項權利，而不是奢侈品”">​</a></h4><p>Google Analytics 除了可以記錄很多用户的操作和交互活動之外，這一節還將介紹一個不太常見的功能，就是可以控制是否對用户的身份進行追蹤。</p><h4 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to “Cookies”">​</a></h4><p>Google Analytics 追蹤用户活動的方式是基於 Cookies 的，因此我們可以自定義 Cookies 的名稱以及一些其它的內容，請看下面這段代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trackingID =</span></span>
<span class="line"><span>    &#39;UA-139883813-1&#39;</span></span>
<span class="line"><span>;</span></span>
<span class="line"><span>cookieParams = {</span></span>
<span class="line"><span>    cookieName: &#39;myGACookie&#39;,</span></span>
<span class="line"><span>    cookieDomain: window.location.hostname,</span></span>
<span class="line"><span>    cookieExpires: 604800</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>ngOnInit() {</span></span>
<span class="line"><span>    ga(&#39;create&#39;, this.trackingID, this.cookieParams);</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面這段代碼中，我們設置了 Google Analytics Cookies 的名稱、域以及過期時間，這就讓我們能夠將不同網站或 Web 應用的 Cookies 區分開來。因此我們需要為我們自己的應用程序的 Google Analytics 追蹤器的 Cookies 設置一個自定義的標識1，而不是一個自動生成的隨機標識。</p><h4 id="ip-匿名" tabindex="-1">IP 匿名 <a class="header-anchor" href="#ip-匿名" aria-label="Permalink to “IP 匿名”">​</a></h4><p>在某些場景下，我們可能不需要知道應用程序的流量來自哪裏。例如對於一個按鈕點擊的追蹤器，我們只需要關心按鈕的點擊量，而不需要關心點擊者的地理位置。在這種場景下，Google Analytics 允許我們只追蹤用户的操作行為，而不獲取到用户的 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ipParams = {</span></span>
<span class="line"><span>    anonymizeIp: true</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>ngOnInit() {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    ga(&#39;set&#39;, this.ipParams);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面這段代碼中，我們將 Google Analytics 追蹤器的 <code>abibymizeIp</code> 參數設置為 <code>true</code>。這樣用户的 IP 地址就不會被 Google Analytics 所追蹤，這可以讓用户知道自己的隱私正在被保護。</p><h4 id="不被跟蹤" tabindex="-1">不被跟蹤 <a class="header-anchor" href="#不被跟蹤" aria-label="Permalink to “不被跟蹤”">​</a></h4><p>還有些時候用户可能不希望自己的行為受到追蹤，而 Google Analytics 也允許這樣的需求。因此也存在讓用户不被追蹤的選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>optOut() {</span></span>
<span class="line"><span>    window[&#39;ga-disable-UA-139883813-1&#39;] = true;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>...</span></span></code></pre></div><p><code>optOut()</code> 是一個自定義函數，它可以禁用頁面中的 Google Analytics 追蹤，我們可以使用按鈕或複選框上得事件綁定來使用這一個功能，這樣用户就可以選擇是否會被 Google Analytics 追蹤。</p><p>在本文中，我們討論了 Google Analytics 集成到單頁應用時的難點，並探索出了一種相關的解決方法。我們還了解到了如何在單頁應用中追蹤頁面訪問和用户交互，例如按鈕點擊、社交媒體活動等。</p><p>最後，我們還了解到 Google Analytics 為用户提供了保護隱私的功能，尤其是用户的一些隱私數據並不需要參與到統計當中的時候。而用户也可以選擇完全不受到 Google Analytics 的追蹤。除此以外，Google Analytics 還可以做到很多其它的事情，這就需要我們繼續不斷探索了。</p><hr>`,57)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),l(n,{href:"https://opensourceforu.com/2019/10/all-that-you-can-do-with-google-analytics-and-more/"},{default:i(()=>[...a[6]||(a[6]=[s("https://opensourceforu.com/2019/10/all-that-you-can-do-with-google-analytics-and-more/",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("作者：",-1)),l(n,{href:"https://opensourceforu.com/author/ashwin-sathian/"},{default:i(()=>[...a[8]||(a[8]=[s("Ashwin Sathian",-1)])]),_:1}),a[13]||(a[13]=s(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[14]||(a[14]=s(" 譯者：",-1)),l(n,{href:"https://github.com/HankChow"},{default:i(()=>[...a[10]||(a[10]=[s("HankChow",-1)])]),_:1}),a[15]||(a[15]=s(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...a[11]||(a[11]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[18]||(a[18]=s("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[16]||(a[16]=[s("LCTT",-1)])]),_:1}),a[19]||(a[19]=s(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...a[17]||(a[17]=[s("Linux中國",-1)])]),_:1}),a[20]||(a[20]=s(" 榮譽推出",-1))])])}const C=t(d,[["render",g]]);export{A as __pageData,C as default};
